@startuml

class Person {
  + taxCode : string
  + address : string
  + phoneNumber : string
}

class RepairShop {
  + name : string
  + address : string
  + numberOfEmployees : int
}

class Employee extends Person {
  + yearsOfService : int
}

class Director extends Employee {
  + age : int
}

class Repair {
  + code : string
  + checkInTime : time
  + checkInDate : date
  + returnTime : time
  + returnDate : date
}

class Vehicle {
  + model : string
  + type : string
  + licensePlate : string
  + registrationYear : int
}

class Owner extends Person {}

class Customer extends Person {}

RepairShop "1" -- "1" Director : manages
RepairShop "1" -- "*" Employee : employs
RepairShop "1" -- "*" Repair : performs
Repair "1" -- "1" Vehicle : involves
Vehicle "1" -- "1" Owner : belongs to
Vehicle "1" -- "0..*" Repair : undergoes
Owner "1" -- "0..*" Vehicle : owns
Customer "1" -- "0..*" Vehicle : owns
Customer "1" -- "0..*" Repair : brings

@enduml

